"""Hand-drawn integer-pixel silhouettes. Run: python tools/build-relic-atlas.py."""
from pathlib import Path
import json
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parents[1]
INK = '#12091A'
G, GH, GS = '#DCA64C', '#FFF1B1', '#86512E'
J, JH, JS = '#43AA8B', '#B2F2CB', '#23564F'
B, BH, BS = '#68B9E1', '#E2FCFF', '#3B5683'
R, RH, RS = '#DC6658', '#FFD08C', '#73324A'
P, PH, PS = '#A27BC9', '#E9C7F1', '#53395F'
W, S = '#D9DCC7', '#B8886B'
IDS = 'kimquy giong thachsan sontinh thuytinh cuoi ankh hermes ariadne mjolnir wukong phoenix chudong tam antiem traucau aegis aladdin jack cinderella power vitality haste spirit wildfire dashshock split pierce vampire chain cooling dom'.split()

def relic(kind):
    im = Image.new('RGBA', (32, 32)); d = ImageDraw.Draw(im)
    def p(points, c): d.polygon(points, fill=c, outline=INK)
    def e(box, c): d.ellipse(box, fill=c, outline=INK)
    def l(points, c=GH, width=1): d.line(points, fill=c, width=width)
    def box(x0,y0,x1,y1,c): d.rectangle((x0,y0,x1,y1), fill=c, outline=INK)
    if kind == 'kimquy':
        p([(9,6),(16,4),(24,10),(25,18),(21,24),(14,28),(18,21),(19,14),(13,12),(9,14)],G);p([(14,8),(21,11),(22,18),(19,22),(19,14)],GS);l([(11,8),(15,6),(22,11)])
        e((8,4,15,11),J);l([(10,6),(12,5)],JH);p([(2,14),(6,12),(8,16),(5,19)],G);p([(24,3),(29,5),(27,9),(23,7)],J);p([(25,23),(29,24),(28,29),(24,27)],G);p([(4,24),(8,23),(10,27),(6,30)],J)
    elif kind == 'giong':
        p([(10,8),(16,4),(21,7),(20,25),(15,29),(10,26)],G);box(10,11,21,13,GS);box(10,21,20,23,GS);l([(12,8),(12,10)],GH);l([(13,15),(17,17),(14,19),(18,20)],INK)
        p([(9,9),(5,7),(6,1),(11,6),(14,1),(15,6)],R);p([(11,25),(12,30),(18,31),(23,26),(18,28),(16,25)],R);p([(21,9),(29,5),(25,12)],J);p([(7,17),(1,12),(3,21)],G);p([(22,23),(30,19),(27,26)],G)
    elif kind == 'thachsan':
        p([(11,24),(10,18),(13,14),(14,6),(19,6),(18,17),(23,22),(21,28),(14,30)],GS);e((8,16,24,29),G);e((11,19,21,27),RS);p([(14,7),(14,2),(20,1),(24,4),(20,5),(19,9)],G)
        for x in [14,16,18]: l([(x,7),(x,25)],BH)
        l([(13,18),(11,22),(12,25)],GH);d.arc((1,8,12,23),80,280,fill=B);d.arc((21,9,31,25),280,80,fill=JH)
    elif kind == 'sontinh':
        p([(5,21),(16,17),(27,21),(26,29),(15,31),(5,27)],GS);p([(5,20),(16,16),(27,20),(15,25)],G);l([(8,22),(15,24),(24,21)],GH)
        p([(6,18),(11,5),(15,12),(19,2),(27,18),(19,22)],J);p([(12,14),(19,2),(19,17),(24,18),(18,20)],JS);l([(10,9),(11,6),(13,11)],JH);l([(17,8),(19,4),(21,8)],W);l([(3,16),(11,16),(14,14),(24,14),(29,16)],W,2)
    elif kind == 'thuytinh':
        p([(16,1),(20,8),(26,16),(27,23),(23,28),(15,31),(7,27),(4,21),(7,14)],BS);p([(16,4),(18,12),(23,18),(23,24),(17,28),(10,25),(8,19)],B);l([(12,10),(8,18),(8,22)],BH,2);d.arc((10,13,22,26),20,310,fill=JH,width=2);p([(21,14),(24,16),(22,18),(24,20),(20,19),(18,16)],J);d.point((21,16),fill=GH)
    elif kind == 'cuoi':
        p([(15,29),(6,21),(3,12),(6,5),(14,6),(19,2),(27,6),(29,15),(24,22)],J);p([(15,26),(17,8),(25,6),(26,15),(21,22)],JS);l([(15,28),(17,10),(19,6)],GH);l([(16,22),(8,14),(7,9)],JH);l([(17,17),(24,11)],JH);l([(15,27),(15,31)],G,2);e((12,27,17,31),BH);d.arc((1,1,30,30),200,300,fill=W)
    elif kind == 'ankh':
        e((9,1,23,17),G);e((13,5,19,12),BS);box(13,14,19,29,G);box(5,15,27,20,G);box(14,18,18,28,GS);e((12,13,20,21),R);l([(11,4),(15,2),(19,3)],GH);l([(7,16),(11,16)],GH);d.point((14,15),fill=RH);l([(24,5),(27,3)],G)
    elif kind == 'hermes':
        p([(11,7),(19,7),(18,20),(27,22),(29,26),(27,29),(9,29),(7,25)],GS);p([(12,9),(18,9),(15,22),(25,24),(26,27),(11,26)],G);l([(13,12),(17,12)],GH);l([(12,16),(16,16)],GH)
        p([(12,18),(3,15),(1,7),(5,10),(3,3),(8,7),(9,1),(14,8)],W);l([(11,15),(5,7)],BH);l([(2,27),(6,27)],JH);l([(3,30),(8,30)],B)
    elif kind == 'ariadne':
        p([(10,3),(21,3),(23,7),(19,9),(19,23),(24,25),(22,29),(9,29),(7,25),(12,22),(12,9),(7,7)],W);box(9,10,22,22,G)
        for y in range(11,22,3): l([(10,y),(21,y+1)],GS);l([(11,y),(20,y)],GH)
        l([(22,16),(29,15),(29,6),(26,4),(26,10),(24,10)],G,2);l([(10,5),(14,5),(14,7)],GS)
    elif kind == 'mjolnir':
        p([(17,14),(22,17),(14,30),(9,27)],GS);l([(14,24),(17,25)],G);l([(12,27),(15,28)],G)
        p([(4,4),(21,2),(28,8),(26,17),(9,20),(2,13)],BS);p([(4,4),(20,3),(19,13),(9,17),(3,12)],B);p([(20,4),(26,8),(25,15),(20,16)],JS);l([(5,6),(18,4)],BH);l([(9,7),(9,13),(13,11),(13,8),(16,10)],BH);l([(26,20),(29,22),(26,25),(30,27)],BH)
    elif kind == 'wukong':
        l([(6,29),(14,22),(18,16),(18,9),(23,3)],INK,5);l([(6,28),(14,21),(17,16),(17,9),(22,3)],G,3);l([(9,26),(15,20),(17,14)],GH)
        for y in range(8,23,3): l([(17,y),(24,y-3)],G)
        e((14,2,22,7),W);e((19,0,27,6),GH);e((22,3,30,8),W);d.arc((4,10,23,22),180,360,fill=R,width=2);l([(2,15),(6,12)],RH)
    elif kind == 'phoenix':
        p([(5,29),(12,17),(10,13),(13,12),(13,7),(18,10),(22,1),(29,5),(27,14),(23,15),(24,21),(18,21),(15,26)],RS);p([(9,25),(17,12),(22,3),(26,5),(25,12),(21,16),(21,19),(15,21)],R);l([(6,29),(22,7)],G,2);l([(13,20),(20,18)],RH);l([(18,13),(25,10)],RH);p([(3,8),(5,4),(7,9),(5,12)],G);p([(26,25),(29,20),(30,27)],R)
    elif kind == 'chudong':
        l([(9,29),(20,6)],INK,5);l([(9,28),(20,6)],GS,3);p([(3,15),(17,5),(29,14),(24,18),(10,19)],G);l([(7,14),(17,7),(25,13)],GH);l([(10,16),(24,15)],GS);e((2,23,6,28),J);e((25,21,29,26),JH);e((23,2,27,7),J)
    elif kind == 'tam':
        e((4,16,27,30),G);p([(7,9),(13,15),(21,14),(27,10),(29,16),(26,21),(8,24),(3,21),(3,17)],R);p([(7,19),(13,21),(25,18),(24,21),(9,23)],RS);l([(9,18),(13,16),(17,18),(14,20),(11,18)],GH);l([(19,18),(22,16),(24,17)],G);p([(13,15),(15,10),(19,13)],J)
    elif kind == 'antiem':
        p([(2,10),(29,9),(27,20),(22,27),(13,29),(5,23)],JS);p([(4,11),(27,10),(25,20),(21,24),(13,27),(7,22)],JH);p([(5,11),(26,11),(23,20),(20,23),(13,25),(8,21)],R)
        for x,y in [(10,16),(19,14),(17,21)]: e((x,y,x+1,y+3),INK)
        l([(4,16),(7,22),(13,27)],J);l([(7,12),(20,12)],RH)
    elif kind == 'traucau':
        p([(14,27),(5,20),(2,10),(6,5),(13,7),(19,3),(24,8),(24,17)],J);l([(14,25),(13,10),(19,6)],JH);e((15,14,26,28),G);p([(18,24),(23,18),(30,22),(27,29),(20,29)],W);p([(7,18),(3,21),(8,26),(16,27),(12,23)],R);l([(17,19),(20,17),(23,18)],GH)
    elif kind == 'aegis':
        e((2,2,30,30),G);e((5,5,27,27),W);e((8,8,24,24),JS);p([(12,10),(20,10),(22,16),(19,22),(14,22),(10,17)],S)
        for pts in [[(10,15),(7,11),(11,7),(14,10)],[(18,10),(22,6),(25,11),(21,14)],[(12,20),(9,24),(14,25)],[(20,19),(24,22),(20,25)]]: l(pts,J,2)
        l([(12,15),(14,15)],JH);l([(18,15),(20,15)],JH);l([(15,19),(18,19)],RS);d.point((7,6),fill=GH)
    elif kind == 'aladdin':
        p([(4,16),(8,13),(20,13),(23,18),(27,15),(30,16),(25,22),(21,23),(12,26),(5,23)],G);p([(5,16),(1,11),(7,13),(10,17)],G);e((8,10,20,14),G);box(13,8,15,11,G);l([(8,17),(18,17),(20,20)],GH);l([(10,22),(17,23)],GS)
        l([(3,12),(6,8),(14,7),(18,3),(23,4),(25,7)],P,3);l([(7,8),(16,6),(19,3)],BH);l([(11,15),(11,20),(14,19),(16,21)],GS)
    elif kind == 'jack':
        e((6,12,25,30),JS);e((8,13,23,27),J);d.arc((10,16,21,26),0,310,fill=GH,width=2);l([(15,17),(16,12),(14,8),(17,3)],JH,2);p([(15,9),(7,3),(7,9),(12,12)],J);p([(16,6),(24,1),(24,7),(18,10)],J);l([(17,4),(24,4)],JH);e((20,10,29,14),W)
    elif kind == 'cinderella':
        p([(3,25),(8,20),(25,20),(30,25),(25,30),(7,30)],PS);l([(7,26),(25,26)],P);p([(8,8),(14,15),(18,18),(24,16),(28,14),(29,21),(24,24),(14,24),(10,20),(8,27),(5,27),(7,18)],B);p([(10,11),(14,17),(21,20),(26,19),(24,22),(14,22),(10,18)],BH);l([(9,12),(10,18)],PH);l([(17,20),(23,20)],PH);e((21,3,24,6),W)
    elif kind == 'power':
        p([(4,8),(8,5),(24,5),(28,9),(26,25),(21,29),(9,29),(5,24)],GS);p([(8,10),(12,8),(16,11),(20,8),(24,11),(24,17),(16,26),(8,18)],RS);p([(10,11),(13,10),(16,13),(20,10),(22,12),(21,18),(16,23),(10,17)],R);p([(13,17),(14,13),(17,16),(18,12),(21,18),(17,21)],GH);l([(5,10),(9,9)],G);l([(8,22),(23,22)],G)
    elif kind == 'vitality':
        e((8,6,25,25),J);e((12,9,21,20),JH);p([(2,27),(5,17),(8,15),(9,4),(14,2),(12,11),(13,17),(9,23),(9,30)],GS);p([(15,30),(17,25),(24,19),(23,9),(28,5),(27,16),(30,23),(25,28)],GS);l([(4,26),(8,19),(11,16)],G);l([(19,27),(26,22),(26,16)],G);p([(10,24),(15,20),(21,22),(17,26),(13,27)],GS)
    elif kind == 'haste':
        l([(4,6),(15,1),(28,6)],R,2);l([(3,7),(29,7)],GS,2)
        for x,y in [(5,22),(10,18),(15,25),(20,20),(25,23)]: box(x,8,x+3,y,J);l([(x+1,10),(x+1,y-2)],JH);box(x,y-2,x+3,y,GS)
        l([(17,25),(17,27)],R);p([(13,26),(20,26),(19,31),(14,31)],JH)
    elif kind == 'spirit':
        for pts in [[(16,27),(2,21),(3,14),(12,18)],[(16,27),(29,22),(29,14),(20,18)],[(16,26),(6,27),(4,22),(12,21)],[(16,26),(25,27),(28,21),(20,21)],[(16,28),(10,19),(16,14),(22,19)]]: p(pts,W)
        e((9,3,24,20),BS);e((10,4,22,18),B);e((12,6,17,11),BH);l([(17,15),(20,12)],JH)
    elif kind == 'wildfire':
        l([(12,5),(12,2),(20,2),(20,5)],GS,2);p([(7,6),(24,6),(29,12),(27,25),(22,29),(10,29),(4,24),(3,12)],GS);p([(8,9),(23,9),(25,13),(24,24),(20,26),(11,26),(7,23),(6,13)],R);l([(10,10),(9,24)],G);l([(22,10),(22,24)],G);p([(12,20),(12,15),(15,16),(18,12),(20,17),(18,20),(14,23)],GH);p([(13,22),(10,22),(9,18),(11,19)],G);box(8,5,23,8,INK)
    elif kind == 'dashshock':
        e((2,4,29,28),GS);e((3,3,29,25),G);e((6,6,26,22),GS);e((8,7,24,20),G);p([(16,5),(18,11),(24,8),(21,14),(28,14),(21,17),(24,22),(18,19),(16,25),(14,19),(7,22),(11,17),(4,14),(11,12),(7,7),(14,10)],GH);e((13,11,19,17),BS);l([(1,2),(5,4),(2,7)],BH);l([(27,25),(30,27),(27,30)],B)
    elif kind == 'split':
        p([(4,5),(12,13),(21,13),(29,5),(27,13),(20,18),(13,18),(6,13)],GS);l([(5,7),(13,14),(21,14),(28,7)],G);l([(6,12),(26,12)],W);p([(14,8),(19,7),(19,25),(16,30),(13,27)],RS);box(13,17,20,21,G)
        for x in [12,16,20]: l([(x,14),(x,3)],B);p([(x-2,4),(x,0),(x+2,4)],BH)
    elif kind == 'pierce':
        p([(15,1),(23,12),(20,17),(17,24),(12,28),(11,18),(7,15)],JS);p([(15,3),(16,18),(13,24),(12,17),(9,14)],BH);p([(17,6),(21,12),(18,18)],J);l([(15,5),(15,20)],W);l([(14,25),(13,31)],GS,3);l([(17,12),(20,13),(17,15)],JH);l([(8,19),(3,21),(6,23)],B)
    elif kind == 'vampire':
        p([(5,6),(27,6),(25,18),(20,23),(18,24),(18,27),(24,29),(23,31),(9,31),(8,29),(14,27),(14,24),(9,21)],RS);p([(7,8),(10,17),(15,20),(16,12),(19,19),(23,15),(25,8)],P);e((6,3,26,10),PS);e((8,4,24,8),R);l([(9,5),(17,5)],RH);l([(11,13),(12,17)],PH);l([(15,25),(16,27)],G);l([(12,2),(10,0)],PH);l([(21,2),(24,0)],PH)
    elif kind == 'chain':
        e((10,6,22,17),PS);e((6,14,26,30),P);e((11,8,18,14),P);l([(9,21),(9,25),(12,27)],PH);l([(11,18),(22,18)],G,2);l([(20,18),(28,22),(26,27)],G);box(13,4,19,8,GS);p([(17,0),(25,1),(20,5),(25,5),(18,10),(20,5),(15,5)],BH)
    elif kind == 'cooling':
        p([(6,4),(15,1),(18,5),(9,12),(2,10)],JS);p([(25,4),(31,12),(26,15),(21,9)],J);p([(2,22),(9,18),(14,26),(8,31),(1,27)],JS);p([(23,21),(30,20),(30,28),(24,31),(19,26)],J);p([(16,5),(24,13),(20,24),(12,26),(7,17),(10,10)],BS);p([(16,7),(21,13),(18,23),(13,23),(10,16)],B);l([(15,10),(13,16),(16,22)],BH,2);l([(9,5),(13,3)],G);l([(25,24),(28,23)],G)
    elif kind == 'dom':
        d.arc((2,2,29,25),10,350,fill=INK,width=6);d.arc((3,3,28,24),10,350,fill=RS,width=4);d.arc((4,4,27,23),180,320,fill=R,width=2);box(1,9,6,15,G);box(3,10,5,13,RS);e((13,17,20,23),GS);e((10,20,24,31),G);l([(12,28),(23,28)],GS);e((15,24,19,28),GS)
        for x,y in [(13,23),(16,21),(20,23)]: d.point((x,y),fill=GH)
