def build():
    atlas=Image.new('RGBA',(256,128))
    for i,k in enumerate(IDS): atlas.paste(relic(k),(i%8*32,i//8*32))
    atlas.save(ROOT/'assets/relics-pixel-v09.png')
    qa=ROOT/'qa/v091';qa.mkdir(parents=True,exist_ok=True)
    sheet=Image.new('RGB',(960,720),'#211B2C');d=ImageDraw.Draw(sheet)
    for i,k in enumerate(IDS):
        x,y=i%8*120,i//8*132;sheet.paste(relic(k).resize((96,96),Image.Resampling.NEAREST),(x+12,y),relic(k).resize((96,96),Image.Resampling.NEAREST));d.text((x+8,y+98),k,fill='#E5D5AD')
    sheet.save(qa/'relic-contact.png')
    fingerprints=[relic(k).tobytes() for k in IDS];assert len(set(fingerprints))==32
    assert set(atlas.getchannel('A').getdata()) == {0,255}
    (qa/'art-report.json').write_text(json.dumps({'relics':32,'uniqueSilhouettes':len({relic(k).getchannel('A').tobytes() for k in IDS}),'binaryAlpha':True}),encoding='utf8')
    print('Built 32 relics. NPCs: design/blender/npcs/build_npcs.py (Blender Mesh + Atlas).')

if __name__=='__main__': build()
